function rebuildScore(){if(!current)return;scoreRows=SC.lines(current,current.lyrics||[],baseTimeline(),Number($('lyricOffset').value)||0);scoreEvents=SC.events(current,baseTimeline());if(current.lyrics?.some(r=>r.chords?.length)){scoreEvents=scoreRows.flatMap(row=>row.chunks.filter(c=>c.chord).map(c=>({time:c.time,chord:c.chord}))).sort((a,b)=>a.time-b.time)}$('scorePaper').replaceChildren();scoreRows.forEach(row=>{const line=document.createElement('div');line.className='score-line';line.dataset.time=row.time;if(row.label){const label=document.createElement('small');label.className='score-section-label';label.textContent=row.label;line.append(label)}row.chunks.forEach((chunk,j)=>{const cell=document.createElement('button');cell.className='score-chunk';cell.dataset.start=chunk.time;cell.dataset.end=row.chunks[j+1]?.time??row.end;cell.innerHTML='<b>'+esc(chunk.chord?T.chord(chunk.chord,transpose-Number($('capo').value)):'\u00a0')+'</b><span>'+esc(chunk.text||' \u00a0 ')+'</span>';cell.setAttribute('aria-label',(chunk.chord||'가사')+' '+chunk.text+' '+format(chunk.time));cell.onclick=()=>{stopSound();seekScore(chunk.time);scoreActive=-999;paint()};line.append(cell)});$('scorePaper').append(line)});scoreBeat=-999;scoreActive=-999;scorePaintKey='';paint()}
