$('detectBeat').onclick=async()=>{if(!current||!hasAudio()){$('beatStatus').textContent='먼저 음원을 연결해주세요.';return}const button=$('detectBeat'),id=current.id;button.disabled=true;$('beatStatus').textContent='음원에서 BPM과 첫 박을 찾고 있습니다…';let ctx;try{const response=await fetch(audio.src),data=await response.arrayBuffer();ctx=new(window.AudioContext||window.webkitAudioContext)();const buffer=await ctx.decodeAudioData(data),mono=new Float32Array(buffer.length);for(let ch=0;ch<buffer.numberOfChannels;ch++){const channel=buffer.getChannelData(ch);for(let i=0;i<mono.length;i++)mono[i]+=channel[i]/buffer.numberOfChannels}const pulse=SC.detectPulse(mono,buffer.sampleRate);if(current?.id!==id)return;if(!pulse)throw Error('박자를 확실히 찾지 못했습니다. 박자 탭과 첫 박 위치로 직접 맞춰주세요.');current.rhythm=pulse;$('bpm').value=pulse.bpm;$('beatOffset').value=pulse.offset.toFixed(2);$('beatStatus').textContent='추정 '+pulse.bpm+' BPM · 첫 박 '+pulse.offset.toFixed(2)+'초. 음원을 들으며 확인·수정해주세요.';scoreBeat=-999;paint()}catch(e){$('beatStatus').textContent=e.message||'음원을 분석하지 못했습니다.'}finally{button.disabled=false;if(ctx)ctx.close()}};
