 fresh();
 for(const row of scoreRows){space(80);if(row.label){ctx.font='bold 11px "Noto Sans KR",sans-serif';ctx.fillStyle='#849476';ctx.fillText(row.label,margin,y-6);y+=16}let x=margin;for(const chunk of row.chunks){const chord=chunk.chord?T.chord(chunk.chord,transpose-Number($('capo').value)):'';ctx.font='17px "Noto Sans KR",sans-serif';const texts=wrapped(ctx,chunk.text||'    ',max);for(let k=0;k<texts.length;k++){const label=k===0?chord:'',text=texts[k];ctx.font='17px "Noto Sans KR",sans-serif';const width=Math.max(ctx.measureText(text).width,label?label.length*10:0);if(x+width>W-margin&&x>margin){y+=67;space(67);x=margin}ctx.font='bold 17px "DM Sans",sans-serif';ctx.fillStyle='#2b795e';ctx.fillText(label,x,y+3);ctx.font='17px "Noto Sans KR",sans-serif';ctx.fillStyle='#26362d';ctx.fillText(text,x,y+31);x+=width;if(k<texts.length-1){y+=67;space(67);x=margin}}}y+=78}
