function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.textContent=name+' 다운로드';if(scoreDownloadLinks.firstChild)URL.revokeObjectURL(scoreDownloadLinks.firstChild.href);scoreDownloadLinks.replaceChildren(a);a.click()}
function decodeImage(canvas){const raw=atob(canvas.toDataURL('image/jpeg',.94).split(',')[1]);return{width:canvas.width,height:canvas.height,bytes:Uint8Array.from(raw,c=>c.charCodeAt(0))}}
async function exportScore(type){if(!current)return;const token=++scoreRenderToken,songId=current.id;$('exportPdf').disabled=$('exportPng').disabled=true;$('exportStatus').textContent='악보 파일을 만들고 있습니다…';try{const pages=await exportPages();if(current.id!==songId||token!==scoreRenderToken)throw Error('곡이 바뀌었습니다. 다시 저장해주세요.');if(type==='pdf'){saveBlob(new Blob([SC.pdf(pages.map(decodeImage))],{type:'application/pdf'}),current.title+'-코드악보.pdf')}else if(pages.length===1){const blob=await new Promise(resolve=>pages[0].toBlob(resolve,'image/png'));saveBlob(blob,current.title+'-코드악보.png')}else{$('scoreImageLinks').replaceChildren();for(let i=0;i<pages.length;i++){const a=document.createElement('a');a.textContent=(i+1)+'페이지 PNG 저장';a.href=pages[i].toDataURL('image/png');a.download=current.title+'-'+(i+1)+'페이지.png';$('scoreImageLinks').append(a)}pagesDialog.showModal()}$('exportStatus').textContent=pages.length+'페이지 악보를 만들었습니다. 현재 카포·조옮김 코드가 적용됐습니다.'}catch(e){$('exportStatus').textContent=e.message||'파일을 만들지 못했습니다.'}finally{$('exportPdf').disabled=$('exportPng').disabled=false}}
